  if [ "$RETRY_RC" -ne 0 ] && printf '%s\n%s' "$RETRY_OUTPUT" "$RETRY_SECOND_OUTPUT" | grep -Eq 'ENOENT|EBUSY|ENOTEMPTY'; then
    echo "node_modules link/dependency broken — run bun install and retry";
  fi;
  return "$RETRY_RC";
}; retry_transient $spurBin task update "$wbs" done --no-lifecycle

learning-capture:onEnter:1.invocation:
mkdir -p .spur/memory && if test -s .spur/run/wrapup-learnings.md; then
  cat .spur/run/wrapup-learnings.md >> .spur/memory/learnings.md &&
  printf '\n' >> .spur/memory/learnings.md;
else
  echo "wrapup: learning capture missing or empty at $PWD/.spur/run/wrapup-learnings.md - append skipped" >&2;
fi && exit 0

metrics-record:onEnter:0.invocation:
mkdir -p .spur/memory && printf '%s' "$tasks" | jq -r '(if type == "string" then (try fromjson catch .) else . end) | if type == "array" then .[] else empty end' | while IFS= read -r wbs; do
  if [ -n "$wbs" ]; then
    task_json=$($spurBin task show "$wbs" --json 2>/dev/null || true);
    if [ -n "$task_json" ]; then
      feat=$(printf '%s' "$task_json" | jq -r '.frontmatter.feature_id // .feature_id // empty' 2>/dev/null || true);
      stat=$(printf '%s' "$task_json" | jq -r '.frontmatter.status // .status // "unknown"' 2>/dev/null || true);
      verdict="UNKNOWN";
      if [ -f ".spur/run/$wbs-verdict.json" ]; then
        v=$(jq -r '.verdict // "UNKNOWN"' ".spur/run/$wbs-verdict.json" 2>/dev/null || true);
        if [ -n "$v" ]; then verdict="$v"; fi;
      fi;
      ts=$(date -u +"%Y-%m-%dT%H:%M:%SZ");
      printf '{"wbs":"%s","feature_id":"%s","status":"%s","verdict":"%s","timestamp":"%s"}\n' "$wbs" "$feat" "$stat" "$verdict" "$ts" >> .spur/memory/wrapup-metrics.jsonl;
    fi;
  fi;
done && exit 0

feature-transition:onEnter:0.invocation:
if [ -z "$feature" ]; then
  echo "feature-transition: vars.feature is empty — refusing no-op feature sync (mis-invocation, not a blocked sync)" >&2;
  exit 1;
fi; if [ -f plugins/sp/scripts/feature-sync-bounded.ts ]; then
  bun plugins/sp/scripts/feature-sync-bounded.ts "$feature" --spur-bin "$spurBin" --json;
else
  $spurBin feature sync "$feature" --json;
fi; exit 0

precheck:onEnter:0.invocation:
mkdir -p .spur/run && STATUS_FILE=".spur/run/$__runId-pr-precheck.status" && if [ -z "$preReviewCmd" ]; then
  printf 'SKIP\n' > "$STATUS_FILE";
else
  set +e; sh -c "$preReviewCmd"; rc=$?; set -e;
  if [ "$rc" -eq 0 ]; then printf 'PASS\n' > "$STATUS_FILE"; else printf 'FAIL\n' > "$STATUS_FILE"; fi;
fi && exit 0
